// Tópico: mackenzie/bueiro-inteligente/{id_bueiro}/sensor/{campo}
const partes = msg.topic.split('/');
const idBueiro = partes[2];
const campo = partes[4];
const valor = parseFloat(msg.payload);

if (isNaN(valor)) {
    node.warn(`Valor inválido em ${msg.topic}: ${msg.payload}`);
    return null;
}

// Limites de classificação do nível de obstrução (%)
const LIMITE_ATENCAO = 50; // a partir de 50% -> amarelo
const LIMITE_CRITICO = 75; // a partir de 75% -> vermelho

// Guarda a última distância de cada bueiro
const distancias = flow.get('distancias') || {};
if (campo === 'distancia') {
    distancias[idBueiro] = valor;
    flow.set('distancias', distancias);
    return null;
}

// Guarda a última obstrução de cada bueiro (usada para verificar a limpeza)
const obstrucoes = flow.get('obstrucoes') || {};
obstrucoes[idBueiro] = valor;
flow.set('obstrucoes', obstrucoes);

// Classifica o nível
let status;
if (valor >= LIMITE_CRITICO) status = 'vermelho';
else if (valor >= LIMITE_ATENCAO) status = 'amarelo';
else status = 'verde';

msg.topic = idBueiro;
msg.id_bueiro = idBueiro;
msg.status = status;
msg.obstrucao_pct = valor;
msg.distancia_cm = (distancias[idBueiro] !== undefined) ? distancias[idBueiro] : null;

const cores = { verde: 'green', amarelo: 'yellow', vermelho: 'red' };
node.status({ fill: cores[status], shape: 'dot', text: `${idBueiro}: ${valor}% (${status})` });

return msg;

// Cadastro fixo da localização de cada bueiro (latitude, longitude e endereço).
// Para adicionar um novo bueiro, basta incluir uma nova linha aqui.
const cadastroBueiros = {
    bueiro01: {
        latitude: -23.5475,
        longitude: -46.6520,
        endereco: 'Rua da Consolação, 930 - Consolação'
    }
};

const local = cadastroBueiros[msg.id_bueiro];

const campos = {
    obstrucao_pct: msg.obstrucao_pct,
    status: msg.status
};

if (msg.distancia_cm !== null) {
    campos.distancia_cm = msg.distancia_cm;
}

if (local) {
    campos.latitude = local.latitude;
    campos.longitude = local.longitude;
    campos.endereco = local.endereco;
} else {
    node.warn(`Bueiro ${msg.id_bueiro} sem localização cadastrada.`);
}

// [campos, tags]
msg.payload = [campos, { id_bueiro: msg.id_bueiro }];
return msg;

// Bueiro entrou em estado crítico: aciona a grade autolimpante
msg.topic = `mackenzie/bueiro-inteligente/${msg.id_bueiro}/atuador/comando`;
msg.payload = 'limpar';
node.status({ fill: 'blue', shape: 'dot', text: `limpeza solicitada: ${msg.id_bueiro}` });
return msg;

// Após a limpeza, confere a obstrução atual do bueiro
// Saída 1: limpeza NÃO resolveu (alerta à equipe) | Saída 2: limpeza resolveu
const LIMITE_CRITICO = 75;

const idBueiro = msg.topic.split('/')[2];
const obstrucoes = flow.get('obstrucoes') || {};
const distancias = flow.get('distancias') || {};
const atual = obstrucoes[idBueiro];

if (atual === undefined) {
    node.warn(`Sem leitura recente do ${idBueiro} para verificar a limpeza.`);
    return null;
}

msg.id_bueiro = idBueiro;
msg.obstrucao_pct = atual;
msg.distancia_cm = (distancias[idBueiro] !== undefined) ? distancias[idBueiro] : null;

if (atual >= LIMITE_CRITICO) {
    node.status({ fill: 'red', shape: 'dot', text: `${idBueiro}: não resolveu (${atual}%)` });
    return [msg, null];
}
node.status({ fill: 'green', shape: 'dot', text: `${idBueiro}: resolvido (${atual}%)` });
msg.payload = `${idBueiro}: limpeza automática resolveu (obstrução ${atual}%)`;
return [null, msg];

const token = env.get('TELEGRAM_BOT_TOKEN');
const chatId = env.get('TELEGRAM_CHAT_ID');

if (!token || !chatId) {
    node.warn('Configure TELEGRAM_BOT_TOKEN e TELEGRAM_CHAT_ID nas variáveis de ambiente da aba.');
    return null;
}

// Cadastro dos bueiros (mesmo da function "Montar ponto InfluxDB")
const cadastroBueiros = {
    bueiro01: { endereco: 'Rua da Consolação, 930 - Consolação, São Paulo/SP' }
};

const LIMITE_CRITICO = 75;
const LINK_DASHBOARD = env.get('LINK_DASHBOARD') || 'https://vibrantminivan1185.grafana.net';

const local = cadastroBueiros[msg.id_bueiro];
const endereco = local ? local.endereco : 'Endereço não cadastrado';

const obstrucao = Number(msg.obstrucao_pct).toFixed(1).replace('.', ',');

const dataHora = new Date().toLocaleString('pt-BR', {
    timeZone: 'America/Sao_Paulo',
    day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit'
});

const texto =
    `🚨 <b>Limpeza manual necessária – ${msg.id_bueiro}</b>\n` +
    `📍 ${endereco}\n` +
    `\n` +
    `<b>Obstrução:</b> ${obstrucao}% (limite crítico: ${LIMITE_CRITICO}%)\n` +
    `A grade autolimpante foi acionada, mas não removeu os resíduos. ` +
    `Provável acúmulo de material grande (sacos, galhos ou entulho).\n` +
    `\n` +
    `👷 <b>O que fazer:</b> enviar a equipe de zeladoria para limpeza manual, evitando o entupimento do bueiro e o alagamento da via.\n` +
    `\n` +
    `🕘 ${dataHora} · 📊 <a href="${LINK_DASHBOARD}">Ver no dashboard</a>`;

msg.url = `https://api.telegram.org/bot${token}/sendMessage`;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    chat_id: chatId,
    text: texto,
    parse_mode: 'HTML',
    disable_web_page_preview: true
};
return msg;

// mackenzie/bueiro-inteligente/{id_bueiro}/{dispositivo}/conexao
const partes = msg.topic.split('/');
msg.payload = `${partes[2]} / ${partes[3]}: ${msg.payload}`;
return msg;
